  "Ask at 3 a.m. Samsoom already knows the shelf.": "Pregunta a las 3 de la mañana. Samsoom ya conoce el estante.",
  "Samsoom knows our catalogue, grades, hours and shipping. It finds the part, explains the grade, and hands you to a person on WhatsApp the second you need one.": "Samsoom conoce nuestro catálogo, calidades, horario y envíos. Encuentra la pieza, explica la calidad y te pasa a una persona en WhatsApp en cuanto lo necesites.",
