  "Samsoom is typing…": "Samsoom está escribiendo…",
  "Hi, I’m Samsoom. Ask me about a part, a grade, shipping, or whether the shop is open right now.": "Hola, soy Samsoom. Pregúntame por una pieza, una calidad, los envíos o si la tienda está abierta ahora.",
  "Ask about a part, a grade, our hours…": "Pregunta por una pieza, una calidad, el horario…",
