  "Original or Service Pack for the best result, OLED for value, Incell when budget comes first.": "Original o Service Pack para el mejor resultado, OLED por valor, Incell cuando prima el presupuesto.",
  "Original or Service Pack for the best result. OLED is great value. Incell when budget comes first. Every grade is labelled on your order.": "Original o Service Pack para el mejor resultado. OLED tiene gran relación calidad-precio. Incell cuando prima el presupuesto. Cada calidad va indicada en tu pedido.",
  "Yes. We ship every day to the Middle East, Africa, Europe and Asia. Tracked, packed by hand, quoted with your order.": "Sí. Enviamos cada día a Oriente Medio, África, Europa y Asia. Con seguimiento, embalado a mano, cotizado con tu pedido.",
  "Yes. We ship worldwide, mainly to the Middle East, Africa, Europe and Asia. Tracked and securely packed; shipping is quoted with your order.": "Sí. Enviamos a todo el mundo, sobre todo a Oriente Medio, África, Europa y Asia. Con seguimiento y bien embalado; el envío se cotiza con tu pedido.",
  "Our bench in Deira fixes screens, batteries, charging ports and board faults. Try the estimator for a price range.": "Nuestro banco en Deira repara pantallas, baterías, conectores de carga y fallos de placa. Prueba el estimador para ver un rango de precios.",
  "I didn’t catch that one. Try a model and part, like “A54 battery” or “iPhone 13 screen”, or ask about grades, hours or shipping.": "No lo he entendido. Prueba con un modelo y una pieza, como “batería A54” o “pantalla iPhone 13”, o pregunta por calidades, horario o envíos.",
