  "Next working day delivery for most addresses. Delivery is charged at checkout (sample: AED 25, free above AED 500).": "Entrega al siguiente día laborable en la mayoría de direcciones. El envío se cobra al pagar (muestra: AED 25, gratis por encima de AED 500).",
