  "No reviews yet": "Aún no hay reseñas",
  "No separate catalogue, no price lists to ask for. Sign in and the shop shows the trade price next to the retail price on every part, in every grade.": "Sin catálogo aparte ni listas de precios que pedir. Inicia sesión y la tienda muestra el precio de mayorista junto al de venta en cada pieza y grado.",
  "Not on the list? We ship almost anywhere: ask us.": "¿No está en la lista? Enviamos a casi cualquier sitio: pregúntanos.",
  "Not sure it is the right one? Send us your model number on WhatsApp and we will check it for you.": "¿No estás seguro de que sea la correcta? Envíanos el número de modelo por WhatsApp y lo comprobamos.",
