  "Nothing here yet.": "Nada aquí todavía.",
  "Nothing in these terms limits your rights under UAE consumer protection law. Apart from those rights, our liability for a part is limited to repairing, replacing or refunding that part.": "Nada en estas condiciones limita tus derechos según la ley de protección del consumidor de los EAU. Aparte de esos derechos, nuestra responsabilidad por una pieza se limita a repararla, cambiarla o reembolsarla.",
