  "One for customers, one for suppliers, and one we give to our most loyal customers. Each is earned its own way, and each lives in your account.": "Una para clientes, otra para proveedores y otra que damos a nuestros clientes más fieles. Cada una se gana a su manera y todas viven en tu cuenta.",
