  "Only account holders can rate parts, and reviews of parts you bought are marked \"verified purchase\". Reviews must be honest and about the part. We remove reviews that are abusive, off-topic, contain personal data or advertise other businesses.": "Solo los titulares de cuenta pueden valorar piezas, y las reseñas de piezas compradas se marcan como «compra verificada». Deben ser honestas y sobre la pieza. Eliminamos reseñas ofensivas, fuera de tema, con datos personales o que anuncian otros negocios.",
  "Only account holders can rate parts, so every review is from a real customer.": "Solo los titulares de cuenta pueden valorar, así que cada reseña es de un cliente real.",
