  "Orders, stars, points, companies and your chats with Samsoom, all in one place.": "Pedidos, estrellas, puntos, empresas y tus chats con Samsoom, todo en un lugar.",
  "Original (Service Pack) is the part the brand fits. OLED Soft is close to original at a lower price. Incell is a reliable budget LCD. AAA is our best-price grade. Every part is labelled by quality and manufacturer.": "Original (Service Pack) es la pieza que monta la marca. OLED Soft se acerca al original a menor precio. Incell es un LCD económico y fiable. AAA es nuestro grado más barato. Cada pieza lleva calidad y fabricante.",
  "Original (Service Pack): 6 months. OLED Soft: 3 months. Incell and AAA: 1 month. Other parts: as stated on the product. The warranty starts on the invoice date.": "Original (Service Pack): 6 meses. OLED Soft: 3 meses. Incell y AAA: 1 mes. Otras piezas: lo indicado en el producto. La garantía empieza en la fecha de factura.",
  "Original / Compatible · up to 6 months": "Original / Compatible · hasta 6 meses",
  "Original grade · 3 months": "Grado original · 3 meses",
  "Original parts in the brand’s service packaging, the same ones authorised service centres fit. Exact colors, brightness, touch and battery life.": "Piezas originales en el embalaje de servicio de la marca, las mismas que montan los servicios técnicos oficiales. Colores, brillo, tacto y batería exactos.",
  "Original parts recovered and rebuilt (for example a new glass on an original panel), then tested.": "Piezas originales recuperadas y reconstruidas (por ejemplo cristal nuevo sobre un panel original) y luego probadas.",
  "Original · 6 months": "Original · 6 meses",
  "Original · Service Pack": "Original · Service Pack",
  "Original, OLED, Incell and AAA, side by side.": "Original, OLED, Incell y AAA, lado a lado.",
