  "Our staff, according to their role, and the service providers that run the site for us (hosting, database, e-mail, payments, shipping partners for your delivery) under contracts that protect it.": "Nuestro personal, según su función, y los proveedores que gestionan la web (alojamiento, base de datos, e-mail, pagos, socios de envío para tu entrega) bajo contratos que la protegen.",
