  "Physical damage (cracks, bends, pressure marks), liquid damage, parts damaged while being fitted by a third party, parts with removed or altered labels, and normal wear such as battery capacity loss within specification.": "Daños físicos (grietas, dobleces, marcas de presión), daños por líquidos, piezas dañadas al montarlas un tercero, piezas con etiquetas quitadas o alteradas y el desgaste normal, como la pérdida de capacidad de batería dentro de especificación.",
