  "Stock shown on the website is an estimate. If a part is no longer available we tell you before taking payment and offer an alternative or cancel the line.": "El stock de la web es una estimación. Si una pieza ya no está disponible te avisamos antes de cobrar y te ofrecemos una alternativa o anulamos la línea.",
