  "Talk to us.": "Habla con nosotros.",
  "Tell us about you. We read every application and reply to everyone.": "Cuéntanos sobre ti. Leemos cada solicitud y respondemos a todos.",
  "Tell us where and what, and we quote the route and the price, usually the same day.": "Dinos adónde y qué, y te presupuestamos ruta y precio, normalmente en el día.",
  "Terms of sale": "Condiciones de venta",
  "Test every part before it leaves the shop.": "Probar cada pieza antes de que salga de la tienda.",
