  "Thank you! Your review is live.": "¡Gracias! Tu reseña ya está publicada.",
  "Thank you,": "Gracias,",
  "Thank you. We reply by e-mail, usually the same day.": "Gracias. Respondemos por e-mail, normalmente en el día.",
  "Thank you. We will review it and reply within one working day.": "Gracias. Lo revisaremos y responderemos en un día laborable.",
  "The": "La",
  "The brand’s own part": "La pieza de la propia marca",
  "The card for everyone who buys parts or repairs with us. Register online, your first purchase activates it, and every dirham you spend charges it up.": "La tarjeta para todos los que compran piezas o reparan con nosotros. Regístrate online, tu primera compra la activa y cada dírham que gastas la carga.",
  "The fee follows the price of the part. Our technician may adjust it up or down for the part and the work involved, and always tells you before starting.": "La tarifa sigue el precio de la pieza. El técnico puede ajustarla al alza o a la baja según la pieza y el trabajo, y siempre te lo dice antes de empezar.",
  "The fine print,": "La letra pequeña,",
  "The part and the fitting fee both count.": "Cuentan la pieza y la instalación.",
  "The part the brand itself fits, in its service box. Same colors, brightness, touch and battery life as new. Our longest warranty.": "La pieza que monta la propia marca, en su caja de servicio. Mismos colores, brillo, tacto y batería que el nuevo. Nuestra garantía más larga.",
  "The part the brand itself fits.": "La pieza que monta la propia marca.",
  "The people behind the counter.": "Las personas tras el mostrador.",
  "The phones we stock parts for, and the factories behind every part, so you always know exactly what you are buying.": "Los móviles de los que tenemos piezas y las fábricas detrás de cada una, para que siempre sepas exactamente qué compras.",
  "The whole shop": "Toda la tienda",
  "These terms are governed by the laws of the Emirate of Dubai and the federal laws of the UAE. The courts of Dubai have jurisdiction.": "Estas condiciones se rigen por las leyes del Emirato de Dubái y las leyes federales de los EAU. Son competentes los tribunales de Dubái.",
  "This site keeps a few things in your browser so it works: your language, your cart, stars and recent searches, whether you have seen Samsoom’s tour, and your sign-in session. We do not use advertising cookies.": "Esta web guarda algunas cosas en tu navegador para funcionar: tu idioma, tu carrito, estrellas y búsquedas recientes, si has visto el recorrido de Samsoom y tu sesión. No usamos cookies publicitarias.",
  "Three steps to trade prices.": "Tres pasos hacia los precios de mayorista.",
  "Tip: create your account first so the approval is linked to it.": "Consejo: crea primero tu cuenta para que la aprobación quede vinculada.",
  "Title": "Título",
  "To be the parts counter repair shops trust most, from Dubai to Madrid and beyond.": "Ser el mostrador de piezas en el que más confían los talleres, de Dubái a Madrid y más allá.",
  "To sell and deliver parts, run repairs and warranties, approve trade accounts, answer you, keep the accounts required by UAE tax law, and improve the site. We do not sell your data.": "Para vender y entregar piezas, hacer reparaciones y garantías, aprobar cuentas de mayorista, responderte, llevar la contabilidad que exige la ley fiscal de los EAU y mejorar la web. No vendemos tus datos.",
  "Too short": "Demasiado corta",
