  "Up to 6 months": "Hasta 6 meses",
  "Up to 6 months on Original, 3 months on OLED, 1 month on Incell and AAA. It covers faults of the part itself.": "Hasta 6 meses en Original, 3 en OLED y 1 mes en Incell y AAA. Cubre fallos de la propia pieza.",
  "Up to 6 months, by grade.": "Hasta 6 meses, según el grado.",
  "Use “Forgot your password?” on the sign-in page and we e-mail you a reset link.": "Usa «¿Olvidaste tu contraseña?» en la página de acceso y te enviamos un enlace.",
