  "WRITE TO US": "ESCRÍBENOS",
  "Waiting for review": "Pendiente de revisión",
  "Walk in any time we are open, or book a time and skip the queue. We confirm on WhatsApp.": "Ven cuando estemos abiertos o reserva hora y sáltate la cola. Lo confirmamos por WhatsApp.",
  "Warranty & quality": "Garantía y calidad",
  "Warranty & returns": "Garantía y devoluciones",
  "Warranty covers faults from the part itself. It does not cover physical or water damage, or parts fitted elsewhere that were damaged while fitting.": "La garantía cubre fallos de la propia pieza. No cubre daños físicos o por agua, ni piezas montadas en otro sitio que se dañaron al montarlas.",
  "Warranty or return": "Garantía o devolución",
  "Warranty policy": "Política de garantía",
  "We accept cash and card in the shop, bank transfer, and payment links we send after confirming your order. Orders are released for delivery or collection once paid, unless your trade account has approved credit.": "Aceptamos efectivo y tarjeta en tienda, transferencia y enlaces de pago que enviamos tras confirmar tu pedido. Los pedidos se entregan una vez pagados, salvo que tu cuenta de mayorista tenga crédito aprobado.",
  "We book the best route for your parcel: express for urgent parts, air cargo for bulk.": "Elegimos la mejor ruta para tu paquete: exprés para lo urgente, carga aérea para el volumen.",
  "We check the phone in front of you.": "Revisamos el móvil delante de ti.",
  "We confirm on WhatsApp, then send a payment link": "Confirmamos por WhatsApp y luego enviamos un enlace de pago",
  "We help with packing and paperwork, but the shipping cost and the shipper’s terms are between you and your shipper.": "Ayudamos con el embalaje y los papeles, pero el coste y las condiciones del envío son entre tú y tu transportista.",
  "We hire people who like phones, people and getting things exactly right. Openings are samples until the owner publishes real ones.": "Contratamos a gente a la que le gustan los móviles, las personas y hacer las cosas bien. Las vacantes son de muestra hasta que el propietario publique las reales.",
  "We opened WhatsApp with your booking; the team confirms the time there.": "Abrimos WhatsApp con tu reserva; el equipo confirma la hora allí.",
  "We opened WhatsApp with your request; the team replies there.": "Abrimos WhatsApp con tu solicitud; el equipo responde allí.",
  "We quote shipping": "Presupuestamos el envío",
  "We received your application and will be in touch.": "Hemos recibido tu solicitud y te contactaremos.",
  "We received your order. Our team confirms stock, delivery and the final price on WhatsApp, usually within minutes during opening hours.": "Hemos recibido tu pedido. El equipo confirma stock, entrega y precio final por WhatsApp, normalmente en minutos en horario de apertura.",
  "We reply here during opening hours, and by e-mail after.": "Respondemos aquí en horario de apertura y por e-mail fuera de él.",
  "We sent a 6-digit code to": "Enviamos un código de 6 cifras a",
  "We ship door to door with our partners (such as Sky Dragon, Emirates SkyCargo, UPS and DHL) and quote the price and time before you pay. Duties and taxes in the destination country are paid by the receiver unless agreed otherwise.": "Enviamos puerta a puerta con nuestros socios (como Sky Dragon, Emirates SkyCargo, UPS y DHL) y te damos precio y plazo antes de pagar. Aranceles e impuestos en destino los paga el destinatario salvo acuerdo.",
  "We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.": "Enviamos piezas cada semana a talleres y comerciantes de Oriente Medio, África, Europa y Asia: puerta a puerta con nuestros socios o con tu propio transportista.",
  "We ship to 28+ countries every week, door to door, and we can hand your order to your own shipper.": "Enviamos a más de 28 países cada semana, puerta a puerta, y podemos entregar tu pedido a tu propio transportista.",
  "We started in 2003 as Syria Tell. In 2020 the shop took the name Sam Electronics, with the same management and the same people behind the counter.": "Empezamos en 2003 como Syria Tell. En 2020 la tienda pasó a llamarse Sam Electronics, con la misma dirección y las mismas personas tras el mostrador.",
  "We verify and approve": "Verificamos y aprobamos",
