  "you are.": "tú lo estés.",
  "your trade card": "tu tarjeta de mayorista",
  "AED 1 = 1 point, on every part and every repair.": "1 AED = 1 punto, en cada pieza y cada reparación.",
  "AED 1 = 1 point on every part and repair. Your level rises as your points do.": "1 AED = 1 punto en cada pieza y reparación. Tu nivel sube con tus puntos.",
  "The trade card. Apply online with your trade licence; our management team checks it and activates the card by hand. Your monthly volume sets your level.": "La tarjeta de mayorista. Solicítala online con tu licencia comercial; nuestra dirección la revisa y activa la tarjeta a mano. Tu volumen mensual fija tu nivel.",
  "estimate": "estimado",
  "Newest": "Más nuevos",
  "Everything": "Todo",
  "Yes: the part and the fitting fee both count, AED 1 = 1 point.": "Sí: cuentan la pieza y la instalación, 1 AED = 1 punto.",
  "From your approved trade orders in the last 30 days. It is reviewed every month; you never drop more than one level at a time.": "Según tus pedidos de mayorista aprobados de los últimos 30 días. Se revisa cada mes; nunca bajas más de un nivel a la vez.",
  "Send a list on WhatsApp or upload it; we price it the same day.": "Envía una lista por WhatsApp o súbela; la presupuestamos en el día.",
  "Retailer": "Minorista",
  "Corporate": "Empresa",
  "Frames": "Marcos",
  "Sales Lead": "Responsable de ventas",
  "Repair Engineer": "Ingeniero de reparación",
  "Parts Specialist": "Especialista en piezas",
  "Accounts & Front Desk": "Cuentas y recepción",
  "Dispatch Technician": "Técnico de envíos",
  "Plaza Mayor district, Madrid, Spain": "Barrio de Plaza Mayor, Madrid, España",
  "Sales": "Ventas",
  "Knows grades and manufacturers by heart; advises trade customers at the counter and on WhatsApp.": "Se sabe los grados y fabricantes de memoria; asesora a los mayoristas en el mostrador y por WhatsApp.",
  "Operations": "Operaciones",
  "Checks, packs and ships parts worldwide; keeps the stock exact.": "Revisa, empaqueta y envía piezas a todo el mundo; mantiene el stock exacto.",
  "Complaint": "Queja",
  "Partnership": "Colaboración",
  "Prices in the shop are shown without VAT; 5% UAE VAT is added at checkout and shown on your invoice.": "Los precios de la tienda se muestran sin IVA; el 5 % de IVA de los EAU se añade al pagar y figura en tu factura.",
  "Bring or send it back with the invoice within the warranty. We test it; if it is faulty we replace it or refund you. See the returns policy for the details.": "Tráela o envíala con la factura dentro de la garantía. La probamos; si está defectuosa la cambiamos o te devolvemos el dinero. Consulta la política de devoluciones.",
  "Cookies": "Cookies",
  "These terms apply to every sale by Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates (\"Sam Electronics\", \"we\"), in the shop, on this website, on WhatsApp or by phone.": "Estas condiciones se aplican a toda venta de Sam Electronics L.L.C, Al Murar, Deira, Dubái, EAU («Sam Electronics», «nosotros»), en tienda, en esta web, por WhatsApp o por teléfono.",
  "Prices": "Precios",
  "Prices are in UAE dirhams (AED). Prices shown in the shop do not include VAT; 5% UAE VAT is added at checkout and shown on the tax invoice.": "Los precios están en dírhams (AED). Los precios de la tienda no incluyen IVA; el 5 % se añade al pagar y figura en la factura fiscal.",
  "Orders": "Pedidos",
  "Liability": "Responsabilidad",
  "Refunds": "Reembolsos",
  "You may ask us to hand your order to your own shipper or cargo agent. We pack it and share the paperwork; the shipping cost and the shipper’s terms are between you and your shipper, and responsibility passes to you when we hand the parcel over.": "Puedes pedirnos entregar tu pedido a tu transportista o agente de carga. Lo embalamos y compartimos los papeles; el coste y las condiciones del envío son entre tú y tu transportista, y la responsabilidad pasa a ti al entregar el paquete.",
  "You can clear them at any time in your browser; the site will simply forget your cart and preferences on that device.": "Puedes borrarlos cuando quieras en tu navegador; la web simplemente olvidará tu carrito y preferencias en ese dispositivo.",
  "A well-known aftermarket maker with consistent quality and packaging; our usual AAA choice.": "Un fabricante alternativo conocido, de calidad y embalaje constantes; nuestra opción habitual en AAA.",
  "Language": "Idioma",
  "Help: ask Samsoom": "Ayuda: pregunta a Samsoom",
