  "The team updates you on WhatsApp at each step.": "El equipo te avisa por WhatsApp en cada paso.",
  "Repairs you book on this device appear here with their job ticket.": "Las reparaciones que reserves en este dispositivo aparecen aquí con su ticket.",
  "Order": "Pedido",
  "Each part’s warranty is on its label and invoice; bring the order number with the part.": "La garantía de cada pieza está en su etiqueta y factura; trae el número de pedido con la pieza.",
  "Repairs are covered from the day you collect the phone. Bring this ticket.": "Las reparaciones tienen garantía desde el día que recoges el teléfono. Trae este ticket.",
  "We can’t find that number on this account. Check it, or send it to us on WhatsApp and we look it up.": "No encontramos ese número en esta cuenta. Revísalo o envíanoslo por WhatsApp y lo buscamos.",
