  "Your application": "Tu solicitud",
  "Approved. Sign in and the shop shows your trade price on every part.": "Aprobada. Inicia sesión y la tienda mostrará tu precio profesional en cada pieza.",
  "We reply by e-mail and WhatsApp, usually within one working day. Sign in with the same e-mail to see the result here.": "Respondemos por e-mail y WhatsApp, normalmente en un día laborable. Inicia sesión con el mismo e-mail para ver el resultado aquí.",
