  "Every week, out of Dubai.": "Cada semana, desde Dubái.",
  "Planes on the air routes, ships on the sea lanes. Pick a region to see how we ship there.": "Aviones en las rutas aéreas, barcos en las marítimas. Elige una región para ver cómo enviamos allí.",
  "SHIPPING QUOTE": "PRESUPUESTO DE ENVÍO",
