  'More…': 'Más…',
  'Everything on this website and in its systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by the copyright laws of the United Arab Emirates, including Federal Decree-Law No. 38 of 2021. A screenshot for your own reference is fine; copying, sharing or publishing it without our written permission is not.': 'Todo lo que hay en esta web y en sus sistemas (fotos, diseños, textos, precios y datos) pertenece a Sam Electronics y está protegido por las leyes de derechos de autor de los EAU, incluido el Decreto-ley federal n.º 38 de 2021. Una captura para tu propia referencia está bien; copiarla, compartirla o publicarla sin nuestro permiso por escrito, no.',
  'Your connection says you are somewhere else than your device does. Prices, stock and delivery here depend on where you really are, and hiding your location goes against our terms of use. Please switch the VPN off for real prices and delivery times.': 'Tu conexión dice que estás en otro sitio que tu dispositivo. Los precios, el stock y la entrega dependen de dónde estés de verdad, y ocultar tu ubicación va contra nuestras condiciones de uso. Desactiva la VPN para ver precios y plazos reales.',
  'Prices and delivery depend on where you really are. Please switch the VPN off.': 'Los precios y la entrega dependen de dónde estés de verdad. Desactiva la VPN, por favor.',
  'Why am I seeing this?': '¿Por qué veo esto?',
  'Keeping it for yourself is fine; sharing or publishing it needs our permission.': 'Guardarla para ti está bien; compartirla o publicarla necesita nuestro permiso.',
  'Read the full notice': 'Leer el aviso completo',
