  'What each notice on this website means, and every notice this device has been shown.': 'Qué significa cada aviso de esta web, y todos los avisos mostrados en este dispositivo.',
  'Location notice (VPN)': 'Aviso de ubicación (VPN)',
  'Notices shown on this device': 'Avisos mostrados en este dispositivo',
