  'This list stays on this device. The team keeps the same record with your customer ID.': 'Esta lista se queda en este dispositivo. El equipo guarda el mismo registro con tu ID de cliente.',
  'Location mismatch (VPN)': 'Ubicación no coincide (VPN)',
  'Screenshot · copyright notice': 'Captura · aviso de derechos',
  '(Dubai time).': '(hora de Dubái).',
  'Four grades, from best to most affordable:': 'Cuatro calidades, de la mejor a la más económica:',
  'I’m Samsoom, the Sam Electronics phone! I know every part in our shop, the grades, the prices, our hours and where we ship. For anything I can’t do, I’ll pass you to a real person.': '¡Soy Samsoom, el móvil de Sam Electronics! Conozco cada pieza, las calidades, los precios, el horario y adónde enviamos. Para lo demás, te paso con una persona.',
  'No': 'No hay',
  'Our second branch is coming to Plaza Mayor in Madrid. The opening date will be announced on the website and our channels.': 'Nuestra segunda tienda llega a la Plaza Mayor de Madrid. La fecha de apertura se anunciará en la web y nuestros canales.',
  'Packed in Deira, tracked to your door; the shipping cost is quoted with your order.': 'Empaquetado en Deira, con seguimiento hasta tu puerta; el envío se cotiza con tu pedido.',
  'Popular': 'Populares',
  'Prices are samples until the team confirms them.': 'Los precios son de muestra hasta que el equipo los confirme.',
  'Sam Electronics is a family business, run by the same management since 2003, first as Syria Tell, on the same street in Deira.': 'Sam Electronics es un negocio familiar, con la misma dirección desde 2003, primero como Syria Tell, en la misma calle de Deira.',
  'Tell me your model and I’ll show you the price of each grade.': 'Dime tu modelo y te enseño el precio de cada calidad.',
  'We have': 'Tenemos',
  'We have been in Deira since 2003, first as Syria Tell. Same family, same street.': 'Estamos en Deira desde 2003, primero como Syria Tell. Misma familia, misma calle.',
  'Which part do you need?': '¿Qué pieza necesitas?',
  'Which phone is it for?': '¿Para qué móvil es?',
  'Why did the phone wear glasses? It lost its contacts. 📱 Now, can I find you a part?': '¿Por qué el móvil lleva gafas? Perdió sus contactos. 📱 ¿Te busco una pieza?',
  'Yes, we ship to': 'Sí, enviamos a',
  'You can follow every order, step by step, in My Bench → Orders. Sign in with the e-mail you ordered with; the team also updates you on WhatsApp.': 'Puedes seguir cada pedido paso a paso en My Bench → Pedidos. Entra con el e-mail del pedido; el equipo también te avisa por WhatsApp.',
  'ask us': 'pregúntanos',
  'closed.': 'cerrado.',
  'fitted in Deira': 'instalado en Deira',
  'here is what we have': 'esto es lo que tenemos',
  'on our list, but no parts are online for it yet. The team can check the shelf for you on WhatsApp.': 'en la lista, pero aún sin piezas online. El equipo puede mirar la estantería por WhatsApp.',
  'online yet. The team can check the shelf for you on WhatsApp.': 'aún online. El equipo puede mirar la estantería por WhatsApp.',
  'open': 'abierto',
  'Good morning!': '¡Buenos días!',
  'Good afternoon!': '¡Buenas tardes!',
  'Good evening!': '¡Buenas noches!',
  'Hi! What can I find for you today?': '¡Hola! ¿Qué te busco hoy?',
  'Hello there! Looking for a part, a repair, or just saying hi?': '¡Hola! ¿Buscas una pieza, una reparación o solo saludas?',
  'Hey! Tell me your phone model and I’ll take it from there.': '¡Hola! Dime el modelo de tu móvil y yo me encargo.',
  'Welcome! Ask me anything about phones and parts.': '¡Bienvenido! Pregúntame lo que sea sobre móviles y piezas.',
  'Hey hey! What’s up? Need a part?': '¡Hey! ¿Qué tal? ¿Necesitas una pieza?',
  'Yo! Samsoom here. What are we fixing?': '¡Ey! Aquí Samsoom. ¿Qué arreglamos?',
  'Doing great, thanks for asking! And you?': '¡Genial, gracias por preguntar! ¿Y tú?',
  'Fully charged and ready to help! How about you?': '¡Cargado al 100 % y listo para ayudar! ¿Y tú?',
  'All good here in Deira. How is your day going?': 'Todo bien aquí en Deira. ¿Qué tal tu día?',
  'Glad to hear it! What can I do for you?': '¡Me alegro! ¿Qué puedo hacer por ti?',
  'Nice! So, what are we fixing today?': '¡Genial! Entonces, ¿qué arreglamos hoy?',
  'Great! Tell me what you need.': '¡Genial! Dime qué necesitas.',
  'Perfect. What’s the phone model?': 'Perfecto. ¿Qué modelo de móvil es?',
  'Okay! Ask me anything.': '¡Vale! Pregúntame lo que quieras.',
  'No problem. I’m here if you change your mind.': 'Sin problema. Aquí estoy si cambias de idea.',
  'Alright! Anything else I can help with?': '¡Vale! ¿Te ayudo con algo más?',
  'Anytime!': '¡Cuando quieras!',
  'You’re welcome! Anything else I can do?': '¡De nada! ¿Algo más?',
  'My pleasure. I’m here if you need more.': 'Un placer. Aquí estoy si necesitas más.',
  'Happy to help!': '¡Encantado de ayudar!',
  'Bye for now! Come back any time.': '¡Hasta pronto! Vuelve cuando quieras.',
  'Take care! Your phone is in good hands with us.': '¡Cuídate! Tu móvil está en buenas manos.',
  'See you soon!': '¡Hasta pronto!',
  'No worries at all!': '¡No pasa nada!',
  'All good, nothing to apologise for.': 'Todo bien, no hay nada que perdonar.',
  'Don’t worry about it!': '¡No te preocupes!',
  'I’m sorry about this.': 'Lo siento mucho.',
  'I understand, and I want to fix it.': 'Lo entiendo y quiero solucionarlo.',
  'Sorry for the trouble.': 'Perdona las molestias.',
  'Quick answer:': 'Respuesta rápida:',
