  'Shop commercial: screens, every grade, battery week, trade prices, worldwide shipping.': 'Anuncio de la tienda: pantallas, cada calidad, semana de baterías, precios profesionales, envío mundial.',
  'The big box plays our latest offers. Pick a tab, a part or a brand and it shows that topic\'s own deals.': 'El recuadro grande muestra nuestras últimas ofertas. Elige una pestaña, una pieza o una marca y verás sus propias ofertas.',
  'The coloured tag is the quality (Original, OLED, Incell, AAA and more). The dark tag with a light is who made it.': 'La etiqueta de color es la calidad (Original, OLED, Incell, AAA y más). La oscura con una luz es el fabricante.',
  'Star a part to keep it in My Bench. The two-cards button adds it to Compare: up to three parts side by side.': 'Marca una pieza con estrella para guardarla en My Bench. El botón de dos tarjetas la añade a Comparar: hasta tres piezas lado a lado.',
  'Sort by price, newest or best match, and switch between the grid and the list.': 'Ordena por precio, novedad o relevancia, y cambia entre cuadrícula y lista.',
  'Repair shops and traders: apply once, and every part shows your trade price.': 'Talleres y revendedores: solicita una vez y cada pieza muestra tu precio profesional.',
