  'COMPLAINTS': 'RECLAMACIONES',
  'Something went wrong?': '¿Algo salió mal?',
  'Tell us everything.': 'Cuéntanoslo todo.',
  'Every complaint gets a case number and goes straight to the management team. We answer within one working day.': 'Cada reclamación recibe un número de caso y va directa a la dirección. Respondemos en un día laborable.',
