  'Phone or WhatsApp': 'Teléfono o WhatsApp',
  'Repair shops and traders paste a whole parts list and get it priced and checked against stock in one go, with trade prices.': 'Talleres y comerciantes pegan una lista entera y la reciben con precios y stock de una vez, con precios profesionales.',
  'Add your phone under My devices and the shop marks every part that fits. Not sure of your model? Use Find My Part, ask Samsoom, or send him a photo of Settings → About.': 'Añade tu móvil en Mis dispositivos y la tienda marca cada pieza compatible. ¿No sabes tu modelo? Usa Find My Part, pregunta a Samsoom o envíale una foto de Ajustes → Información.',
  'Tip: send the team a photo of the label on the old part and they will match it for you.': 'Consejo: envía al equipo una foto de la etiqueta de la pieza vieja y te la emparejan.',
  'Tip: bring the phone with the battery above 20% so the team can test it straight away.': 'Consejo: trae el móvil con más del 20 % de batería para probarlo al momento.',
  'Tip: trade accounts see trade prices on every part once approved.': 'Consejo: las cuentas profesionales ven su precio en cada pieza una vez aprobadas.',
  'Settings → General → About → Model Number. Tap it once to see the A-number (e.g. A2633). Or read it on the SIM tray slot.': 'Ajustes → General → Información → Número de modelo. Tócalo una vez para ver el número A (p. ej. A2633). O léelo en la ranura de la SIM.',
  'Settings → About phone → Model number (SM-A546B…). Also on the box label.': 'Ajustes → Acerca del teléfono → Número de modelo (SM-A546B…). También en la etiqueta de la caja.',
  'Settings → About phone → Model (e.g. GD1YQ).': 'Ajustes → Acerca del teléfono → Modelo (p. ej. GD1YQ).',
  'Shop here': 'Comprar aquí',
  'Shopping here': 'Comprando aquí',
  'Pick up today · ready in 20 minutes': 'Recoge hoy · listo en 20 minutos',
