  'FRAMES': 'MARCOS',
  'Screens, batteries, flex cables and every small part, for every popular model. Tested, graded and ready at the counter in Deira, or shipped to your door.': 'Pantallas, baterías, flex y cada pieza pequeña, para cada modelo popular. Probadas, clasificadas y listas en el mostrador de Deira, o enviadas a tu puerta.',
  'Original is the part the phone maker fits. Compatible is made by a third party to fit and work like it. Standard is everyday quality at a fair price. AAA is a high-grade copy close to the original, and AA a step under it. OLED Soft, OLED Big and OLED Small are OLED screens (flexible, full-size or compact panels). Incell is an LCD with the touch built in, the budget choice. Other means a quality we source on request. Every part shows its grade as a coloured tag.': 'Original es la pieza que monta el fabricante. Compatible la hace un tercero para encajar y funcionar igual. Standard es calidad del día a día a precio justo. AAA es una copia de alta gama cercana a la original, y AA un paso por debajo. OLED Soft, OLED Big y OLED Small son pantallas OLED (paneles flexibles, completos o compactos). Incell es un LCD con táctil integrado, la opción económica. Other es una calidad bajo pedido. Cada pieza muestra su calidad con una etiqueta de color.',
